from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            -100, 100, timedelta(days=0), timedelta(days=365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._held_contract = None
        self._entry_order_id = None
        self._exit_order_ids = set()
        self._entry_fill_price = None
        self._no_entry_date = None
        self._signal_bar_end = None

        self._five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self._five_minute_consolidator
        )

    def OnFiveMinuteBar(self, sender, bar):
        # The five-minute consolidator uses the SPY exchange (New York) clock.
        # Its regular-session first bar is 09:30-09:35.
        previously_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        # Missing source bars produce no consolidated bar, so nothing is filled in.
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            previously_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and eligible_time
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self._signal_bar_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyEquityPosition()
        self.HandleExpirationSafety()
        self.HandleOpenPositionExit(data)

        if self._signal_bar_end is None or self.Time != self._signal_bar_end:
            return

        self._signal_bar_end = None

        if self._no_entry_date == self.Time.date():
            return

        if self._held_contract is not None and self.Portfolio[self._held_contract].Invested:
            return

        if self._entry_order_id is not None:
            return

        self.TryEnterFromCurrentSlice(data)

    def TryEnterFromCurrentSlice(self, data):
        if not data.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no option chain in current Slice.")
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            contracts.extend(chain.Contracts.Values)

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not valid_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket.OrderId > 0:
            self._entry_order_id = ticket.OrderId
            self._held_contract = selected.Symbol
            self._entry_fill_price = None
            self.Debug(
                f"{self.Time}: Submitted entry for {selected.Symbol}, "
                f"expiry {selected_expiry}, strike {selected.Strike}."
            )
        else:
            self.Debug(f"{self.Time}: Entry skipped: market order was not accepted.")

    def HandleOpenPositionExit(self, data):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        if self._entry_fill_price is not None:
            contract = self.GetContractFromCurrentSlice(data, self._held_contract)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= self._entry_fill_price * 1.50:
                        self.SubmitExit("profit target")
                        return

        expiry = self._held_contract.ID.Date.date()
        if self.Time.date() == self.PreviousSpyTradingDay(expiry) and \
                self.Time.time() == time(15, 45):
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationSafety(self):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        expiry = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self._no_entry_date = self.Time.date()
            self.Debug(
                f"{self.Time}: Expiration safety liquidation for {self._held_contract}."
            )
            self.SubmitExit("expiration safety")

    def PreviousSpyTradingDay(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def GetContractFromCurrentSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            if chain.Contracts.ContainsKey(symbol):
                return chain.Contracts[symbol]
        return None

    def SubmitExit(self, reason):
        if self._held_contract is None:
            return

        open_exit_orders = [
            order for order in self.Transactions.GetOpenOrders(self._held_contract)
            if order.Id != self._entry_order_id
        ]

        if open_exit_orders:
            return

        # Explicitly cancel any pre-existing exit orders before the market exit.
        for order_id in list(self._exit_order_ids):
            self.Transactions.CancelOrder(order_id)

        quantity = -self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_contract, quantity)
        if ticket.OrderId > 0:
            self._exit_order_ids.add(ticket.OrderId)
            self.Debug(f"{self.Time}: Submitted {reason} exit for {self._held_contract}.")

    def HandleUnexpectedSpyEquityPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.Transactions.GetOpenOrders(self.spy):
            return

        self.Debug(
            f"{self.Time}: Unexpected SPY equity position detected "
            f"(exercise/assignment); liquidating."
        )
        self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self._entry_order_id:
            if orderEvent.Status == OrderStatus.Filled and orderEvent.FillQuantity > 0:
                self._entry_fill_price = orderEvent.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled for {self._held_contract} "
                    f"at {self._entry_fill_price}."
                )

            if orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._entry_order_id = None

        if orderEvent.OrderId in self._exit_order_ids:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {self._held_contract} "
                    f"at {orderEvent.FillPrice}."
                )

            if orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._exit_order_ids.discard(orderEvent.OrderId)

        if (
            self._held_contract is not None
            and not self.Portfolio[self._held_contract].Invested
            and self._entry_order_id is None
            and not self._exit_order_ids
        ):
            self._held_contract = None
            self._entry_fill_price = None
