from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, DataNormalizationMode.Raw).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 730))

        self.close_history = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.pending_entry_signal = False

        self.close_history.append(float(bar.Close))
        if len(self.close_history) < 20:
            return

        closes = list(self.close_history)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end_time = bar.EndTime.time()
        eligible_time = (
            bar_end_time >= datetime.strptime("09:45", "%H:%M").time()
            and bar_end_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if crossover and eligible_time:
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationExit()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity > 0:
            self.HandleProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.HasOpenEntryOrder():
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        if self.spy not in data.Bars:
            self.Debug(f"{self.Time}: Entry skipped: no current SPY bar in Slice.")
            return

        spy_price = float(data.Bars[self.spy].Close)
        minimum_expiry = self.Time.date() + timedelta(days=7)

        chain = data.OptionChains[self.option_symbol]
        valid_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not valid_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no call at or above 101% of SPY "
                f"for expiry {selected_expiry}."
            )
            return

        contract = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.entry_price = None
        self.held_contract = contract.Symbol
        self.Debug(
            f"{self.Time}: Entry submitted: 1 {contract.Symbol}, "
            f"expiry {selected_expiry}, strike {contract.Strike}."
        )

    def HandleProfitTarget(self, data):
        if self.entry_price is None or self.HasOpenExitOrder():
            return

        if self.option_symbol not in data.OptionChains:
            return

        contract = next(
            (x for x in data.OptionChains[self.option_symbol] if x.Symbol == self.held_contract),
            None
        )
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.CancelOtherOpenExitOrders()
            self.SubmitExit(
                f"{self.Time}: Profit-target exit submitted for {self.held_contract}; "
                f"midpoint {midpoint:.2f}."
            )

    def HandleExpirationExit(self):
        if self.held_contract is None or self.Portfolio[self.held_contract].Quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if not self.HasOpenExitOrder():
                self.CancelOtherOpenExitOrders()
                self.SubmitExit(
                    f"{self.Time}: Expiration safety exit submitted for {self.held_contract}."
                )
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self.IsTradingDayImmediatelyBefore(expiry_date)
            and not self.HasOpenExitOrder()
        ):
            self.CancelOtherOpenExitOrders()
            self.SubmitExit(
                f"{self.Time}: Pre-expiration time-stop exit submitted for {self.held_contract}."
            )

    def IsTradingDayImmediatelyBefore(self, expiry_date):
        candidate = self.Time.date() + timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while candidate < expiry_date:
            candidate_datetime = datetime.combine(candidate, datetime.min.time())
            if exchange.DateIsOpen(candidate_datetime):
                return False
            candidate += timedelta(days=1)

        return candidate == expiry_date

    def SubmitExit(self, message):
        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(message)

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position ({spy_quantity}) detected; liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )

    def CancelOtherOpenExitOrders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
