                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} at {self.entry_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} did not fill.")
                if self.held_contract == order_event.Symbol and self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.entry_price = None

        if order_event.OrderId == self.exit_order_id and order_event.Status == OrderStatus.Filled:
            self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol} at {order_event.FillPrice:.2f}.")
            if self.Portfolio[order_event.Symbol].Quantity == 0:
